package com.ecommerce.controller;
import com.ecommerce.dto.CartDtos.*; import com.ecommerce.model.User; import com.ecommerce.service.*; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/cart") public class CartController { private final CartService cart; private final UserLookupService users; public CartController(CartService cart,UserLookupService users){this.cart=cart;this.users=users;} @GetMapping public CartResponse getCart(Authentication a){return cart.getCart(current(a));} @PostMapping("/items") public CartResponse add(@Valid @RequestBody AddToCartRequest r,Authentication a){return cart.add(current(a),r);} @PutMapping("/items/{itemId}") public CartResponse update(@PathVariable Long itemId,@Valid @RequestBody UpdateCartItemRequest r,Authentication a){return cart.update(current(a),itemId,r);} @DeleteMapping("/items/{itemId}") public void remove(@PathVariable Long itemId,Authentication a){cart.remove(current(a),itemId);} private User current(Authentication a){return users.currentUser(a);} }